examples.template:
CompositionLocalProvider(LocalConfiguration provides locale) {
    @OptIn(ExperimentalMonarchApi::class)
    MonarchShiftRoster(
        members = listOf(
            MonarchShiftRosterMember({{members.0.id}}, {{members.0.name}}, description = {{members.0.description}}),
            MonarchShiftRosterMember({{members.1.id}}, {{members.1.name}}, description = {{members.1.description}}),
            MonarchShiftRosterMember({{members.2.id}}, {{members.2.name}}, description = {{members.2.description}}),
        ),
        shifts = listOf(
            MonarchShiftRosterShift(
                id = {{shifts.0.id}},
                name = {{shifts.0.name}},
                start = {{shifts.0.start}},
                end = {{shifts.0.end}},
                shortName = {{shifts.0.shortName}},
                color = Color(red = {{shifts.0.color.r}}, green = {{shifts.0.color.g}}, blue = {{shifts.0.color.b}}),
            ),
            MonarchShiftRosterShift(
                id = {{shifts.1.id}},
                name = {{shifts.1.name}},
                start = {{shifts.1.start}},
                end = {{shifts.1.end}},
                color = Color(red = {{shifts.1.color.r}}, green = {{shifts.1.color.g}}, blue = {{shifts.1.color.b}}),
            ),
            MonarchShiftRosterShift(
                id = {{shifts.2.id}},
                name = {{shifts.2.name}},
                start = {{shifts.2.start}},
                end = {{shifts.2.end}},
                color = Color(red = {{shifts.2.color.r}}, green = {{shifts.2.color.g}}, blue = {{shifts.2.color.b}}),
            ),
        ),
        from = {{from|millis}},
        value = roster,
        onValueChange = { next, change ->
            roster = next
            // The app saves change.memberId, change.day and change.assignment here.
        },
        today = {{today|millis}},
        timeZone = "UTC",
        is24Hour = true,
        layout = MonarchShiftRosterLayout.Grid,
    )
}

examples.setupTemplate:
var roster by remember {
    mutableStateOf(
        mapOf<String, Map<Long, MonarchShiftRosterAssignment>>(
            {{roster.0.member}} to mapOf(
                {{roster.0.days.0.day|millis}} to MonarchShiftRosterAssignment.Shift({{roster.0.days.0.shift}}),
                {{roster.0.days.1.day|millis}} to MonarchShiftRosterAssignment.Shift({{roster.0.days.1.shift}}),
                {{roster.0.days.2.day|millis}} to MonarchShiftRosterAssignment.Shift({{roster.0.days.2.shift}}),
                {{roster.0.days.3.day|millis}} to MonarchShiftRosterAssignment.{{roster.0.days.3.shift|pascal}},
                {{roster.0.days.4.day|millis}} to MonarchShiftRosterAssignment.{{roster.0.days.4.shift|pascal}},
            ),
            {{roster.1.member}} to mapOf(
                {{roster.1.days.0.day|millis}} to MonarchShiftRosterAssignment.Shift({{roster.1.days.0.shift}}),
                {{roster.1.days.1.day|millis}} to MonarchShiftRosterAssignment.Shift({{roster.1.days.1.shift}}),
                {{roster.1.days.2.day|millis}} to MonarchShiftRosterAssignment.Shift({{roster.1.days.2.shift}}),
                {{roster.1.days.3.day|millis}} to MonarchShiftRosterAssignment.Shift({{roster.1.days.3.shift}}),
            ),
            {{roster.2.member}} to mapOf(
                {{roster.2.days.0.day|millis}} to MonarchShiftRosterAssignment.Shift({{roster.2.days.0.shift}}),
                {{roster.2.days.1.day|millis}} to MonarchShiftRosterAssignment.{{roster.2.days.1.shift|pascal}},
            ),
        ),
    )
}
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

